<script setup lang="ts">
import { reactive } from 'vue'; import { useRoute, useRouter } from 'vue-router'; import { ElMessage } from 'element-plus'; import type { FormInstance, FormRules } from 'element-plus'; import { ref } from 'vue'; import { useAuthStore } from '../stores/auth'
const formRef = ref<FormInstance>(); const router = useRouter(); const route = useRoute(); const auth = useAuthStore(); const form = reactive({ username: '', password: '' })
const rules: FormRules = { username: [{ required: true, message: '请输入登录账号', trigger: 'blur' }], password: [{ required: true, message: '请输入密码', trigger: 'blur' }] }
async function submit() { if (!await formRef.value?.validate()) return; await auth.login(form); ElMessage.success('欢迎回来'); const redirect = typeof route.query.redirect === 'string' ? route.query.redirect : '/'; router.replace(redirect) }
</script>
<template><main class="auth-page"><RouterLink class="auth-brand" to="/"><span class="brand-mark">蓝</span><strong>蓝境</strong></RouterLink><section class="auth-card"><div class="auth-intro"><p class="eyebrow">WELCOME BACK</p><h1>重新连接<br>你的海洋世界。</h1><p>登录后可以使用鱼类识别、提交救助问题、申请成为志愿者，并查看自己的处理记录。</p></div><div class="auth-form"><h2>账号登录</h2><p>还没有账号？<RouterLink to="/register">立即注册</RouterLink></p><el-form ref="formRef" :model="form" :rules="rules" label-position="top" @submit.prevent="submit"><el-form-item label="登录账号" prop="username"><el-input v-model="form.username" size="large" autocomplete="username" placeholder="请输入用户名" /></el-form-item><el-form-item label="密码" prop="password"><el-input v-model="form.password" size="large" type="password" show-password autocomplete="current-password" placeholder="请输入密码" /></el-form-item><el-button class="auth-submit" type="primary" size="large" native-type="submit" :loading="auth.loading">登录</el-button></el-form></div></section></main></template>
